// externalities.ts). Data and tasks follow the papers in « past exams/20XX.pdf »; the wording is reconstructed,
// never the official text. Reference results: dossier §16, recalculated — no official marking scheme.
import type { ExamQuestion, RubricItem } from './types';

const R = (id: string, label: string, ...patterns: RegExp[]): RubricItem => ({ id, label, patterns });
const note = (year: number, q: string) => `Sujet ${year}, ${q} — données et consignes du PDF « past exams/${year}.pdf », reformulées ; corrigé : recalculs du dossier (§16), pas un barème officiel.`;
/** Q5 definitions: "plain English" means the mechanism in everyday words, not a technical label. */
const def = (id: string, term: string, tags: string[], rubric: RubricItem[], model: string) =>
  ({ kind: 'text' as const, id, prompt: `Define in plain English, without technical terms: ${term}`, tags, rubric, model });

